alter table public.seo_articles add column if not exists suggested_image_prompt text;
alter table public.seo_articles add column if not exists social_copy jsonb not null default '{}'::jsonb;
alter table public.seo_articles add column if not exists validation_results jsonb not null default '[]'::jsonb;
alter table public.seo_articles add column if not exists auto_selected boolean not null default false;
create table if not exists public.seo_automation_settings (id text primary key default 'autopilot' check(id='autopilot'),enabled boolean not null default true,drafts_per_run int not null default 2 check(drafts_per_run between 1 and 5),candidate_day int not null default 1,employer_day int not null default 3,study_day int not null default 5,publish_hour int not null default 9 check(publish_hour between 0 and 23),auto_topic_selection boolean not null default true,auto_internal_links boolean not null default true,auto_social_drafts boolean not null default true,auto_indexing_request boolean not null default true,updated_at timestamptz not null default now());
create table if not exists public.seo_social_posts (id uuid primary key default gen_random_uuid(),article_id uuid not null references public.seo_articles on delete cascade,platform text not null check(platform in ('linkedin','facebook','instagram','x','newsletter')),content text not null,status text not null default 'review' check(status in ('review','approved','posted','rejected')),scheduled_at timestamptz,posted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(article_id,platform));
create table if not exists public.seo_content_reviews (id uuid primary key default gen_random_uuid(),article_id uuid not null references public.seo_articles on delete cascade,review_period text not null check(review_period in ('7d','30d','60d')),due_at timestamptz not null,status text not null default 'pending' check(status in ('pending','complete','skipped')),clicks int,impressions int,ctr numeric,position numeric,recommendation text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(article_id,review_period));
insert into public.seo_automation_settings(id) values('autopilot') on conflict(id) do nothing;
do $$ declare t text; begin foreach t in array array['seo_automation_settings','seo_social_posts','seo_content_reviews'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())',t||'_admin_all',t);execute format('grant select,insert,update,delete on public.%I to authenticated',t);end loop;exception when duplicate_object then null;end $$;
